const notify=m=>window.combineShell.status(m)
async function api(action,p){const response=await fetch('/api/support/'+action,{cache:'no-store',...(p===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(p)})});if(response.status===401){location.replace('/login.html');throw Error('نشست پایان یافته است.')}const result=await response.json();if(!response.ok)throw Error(result.error||'درخواست انجام نشد.');if(action==='grid-sort'&&p){state.revision=result.revision;state.grids??={};state.grids[p.module]={...state.grids[p.module],sort:p.sort,desc:p.desc};localStateReady=true;setTimeout(()=>localStateReady=false,0)}return result}
async function refresh(){if(localStateReady){localStateReady=false;return}state=await api('state')}
async function act(fn){if(busy)return;busy=true;host.setAttribute('aria-busy','true');document.querySelectorAll('[data-mutation]').forEach(b=>b.disabled=true);try{await fn()}catch(e){notify(e.message)}finally{busy=false;host.removeAttribute('aria-busy');document.querySelectorAll('[data-mutation]').forEach(b=>b.disabled=false)}}
const options=(items,value='',placeholder=null)=>`${placeholder===null?'':`<option value="">${esc(placeholder)}</option>`}${items.map(x=>{const [id,label]=Array.isArray(x)?x:[x,x];return `<option value="${esc(id)}" ${String(id)===String(value)?'selected':''}>${esc(label)}</option>`}).join('')}`
